-- Base topic library: headlines (+ one-line summary and category) that new sites write fresh stories from.
-- Only topics live here; no story text is stored or reused. Superadmins manage it with /v1/library.
CREATE TABLE IF NOT EXISTS library_topics (
  id          TEXT PRIMARY KEY,                    -- slug of the original title (stays the same if the title is edited)
  title       TEXT NOT NULL,
  summary     TEXT NOT NULL DEFAULT '',
  category    TEXT NOT NULL,
  enabled     INTEGER NOT NULL DEFAULT 1,          -- 0 = kept but not offered to new sites
  position    INTEGER NOT NULL DEFAULT 0,          -- order used by "the first N topics"
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS library_topics_pos ON library_topics(position);

-- Which topics each site has already written from, so later batches take the ones it hasn't used.
CREATE TABLE IF NOT EXISTS library_usage (
  topic_id    TEXT NOT NULL,
  site_slug   TEXT NOT NULL,
  task_id     TEXT,
  used_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (topic_id, site_slug)
);
CREATE INDEX IF NOT EXISTS library_usage_site ON library_usage(site_slug);

